def transform(grid):
    # The uniform separator divides the grid into two panels. Return the
    # panel whose dimensions correspond to the larger side of the divider.
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            a, b = grid[:r], grid[r + 1:]
            panel = a if len(a) >= len(b) else b
            break
    else:
        for c in range(w):
            if len({row[c] for row in grid}) == 1:
                left = [row[:c] for row in grid]
                right = [row[c + 1:] for row in grid]
                panel = left if c >= w - c - 1 else right
                break
    from collections import Counter
    counts = Counter(v for row in panel for v in row)
    mark = min(counts, key=counts.get)
    return [[3 if v == mark else max(counts, key=counts.get) for v in row] for row in panel]
