def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid divider and select the patterned panel opposite it.
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            panels = (grid[:r], grid[r + 1:])
            panel = max(panels, key=len)
            break
    else:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                left = [row[:c] for row in grid]
                right = [row[c + 1:] for row in grid]
                panel = left if len(left[0]) >= len(right[0]) else right
                break

    from collections import Counter
    counts = Counter(v for row in panel for v in row)
    background = counts.most_common(1)[0][0]
    return [[3 if v != background else background for v in row] for row in panel]
